{
  "findings": [
    {
      "check_id": "AVD-AZU-0023",
      "title": "Security alert policy does not alert account admins",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "LOW",
      "explanation": "The security alert policy does not include subscription owners or administrators in the email notifications, which may delay response to critical alerts."
    }
  ],
  "patched_code": "resource "azurerm_mssql_server_security_alert_policy" "alertpolicy6" {
  resource_group_name        = azurerm_resource_group.example.name
  server_name                = azurerm_mssql_server.mssql6.name
  state                      = "Enabled"
  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint
  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key
  disabled_alerts = [
    "Sql_Injection",
    "Data_Exfiltration"
  ]
  retention_days  = 20
  email_addresses = [
    "securityengineer@bridgecrew.io"
  ]
  email_account_admins = true
}",
  "fix_summary": "Enabled email notifications to account administrators by setting `email_account_admins` to `true` in the security alert policy."
}
